import com.gregtech.gregtech.worldgen.center.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Records actual shared planner requests. This is not a Minecraft world implementation. */
public final class OriginProbe {
    private record Tile(int x, int y, int z, int legacy, String data) {}
    private static final List<Tile> tiles = new ArrayList<>();
    private static final List<String> drains = new ArrayList<>();
    private static final class Recorder implements OriginWorld {
        private final int minX, minZ;
        private long writes;
        private int lowest = Integer.MAX_VALUE, highest = Integer.MIN_VALUE;
        private String spawn;
        Recorder(int x, int z) { minX=x; minZ=z; }
        public int minY() { return -64; }
        public int maxY() { return 320; }
        public boolean canWrite(int x, int y, int z) {
            return x>=minX && x<minX+16 && z>=minZ && z<minZ+16 && y>=minY() && y<maxY();
        }
        public Block getBlock(int x, int y, int z) { return OriginSupport.NB; }
        public boolean setBlock(int x, int y, int z, Block block, int metadata, int flags) {
            if (!canWrite(x,y,z)) return false;
            writes++; lowest=Math.min(lowest,y); highest=Math.max(highest,y);
            return true;
        }
        public Biome getBiomeGenForCoords(int x, int z) { return new Biome("plains","Plains"); }
        public boolean isInfiniteWaterBiome(String name) { return false; }
        public void setSpawnLocation(int x, int y, int z) { spawn=x+","+y+","+z; }
        public void sign(int x,int y,int z,int side,int flags,String... lines) { throw new AssertionError("Unexpected sign"); }
        public void beacon(int x,int y,int z,String primary,String secondary) { throw new AssertionError("Unexpected beacon"); }
        public void clearNonPlayerEntities(int x,int y,int z,int xx,int yy,int zz) { throw new AssertionError("Unexpected entity mutation"); }
        public void tile(int x,int y,int z,int legacy,String data) {
            if (canWrite(x,y,z)) tiles.add(new Tile(x,y,z,legacy,data));
        }
        public void drain(int x,int y,int z,int side) {
            if (canWrite(x,y,z)) drains.add(x+","+y+","+z+","+side);
        }
    }
    public static void main(String[] args) {
        var nexus=new Recorder(16,-48);
        var layout=new SourceNexus(66,true);
        if (layout.generate(nexus,new OriginWorld.Chunk(nexus,16,-48),0,0,new Random(0))) throw new AssertionError("Wrong Nexus anchor accepted");
        if (!layout.generate(nexus,new OriginWorld.Chunk(nexus,16,-48),16,-48,new Random(0))) throw new AssertionError("Nexus declined");
        System.out.println("NEXUS "+nexus.writes+" "+nexus.lowest+" "+nexus.highest+" "+nexus.spawn);
        var testing=new SourceTesting(66);
        long writes=0;
        int count=0, lowest=Integer.MAX_VALUE, highest=Integer.MIN_VALUE;
        for (int x:new int[]{32,48}) for (int z:new int[]{-48,-32}) {
            var world=new Recorder(x,z);
            if (!testing.generate(world,new OriginWorld.Chunk(world,x,z),x,z)) throw new AssertionError("Testing chunk declined");
            if (!"0,71,0".equals(world.spawn)) throw new AssertionError("Spawn mismatch");
            writes+=world.writes; lowest=Math.min(lowest,world.lowest); highest=Math.max(highest,world.highest); count++;
        }
        System.out.println("TESTING "+count+" "+writes+" "+lowest+" "+highest);
        for (Tile tile:tiles) System.out.println("TILE "+tile.x+" "+tile.y+" "+tile.z+" "+tile.legacy+" "+
            Base64.getEncoder().encodeToString(tile.data.getBytes(StandardCharsets.UTF_8)));
        for (String drain:drains) System.out.println("DRAIN "+drain);
        System.out.println("INVENTORY "+OriginTestInventory.ROWS.size());
    }
}
